    private static int[] mesh(String name,double distance){BufferBuilder buffer=new BufferBuilder(262144);buffer.begin(7,DefaultVertexFormats.BLOCK);GearModels.drawTrack(name,GearRenderer.Affine.identity(),0,0,0,15728880,buffer,distance);return data(buffer);}
